using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using Qms.Domain.Trainings;
namespace Qms.Infrastructure.Persistence.Configurations;
public sealed class TrainingMatrixRuleConfiguration:IEntityTypeConfiguration<TrainingMatrixRule>{public void Configure(EntityTypeBuilder<TrainingMatrixRule>b){b.ToTable("matrix_rule","training");b.HasKey(x=>x.Id);b.Property(x=>x.Position).HasMaxLength(160).IsRequired();b.Property(x=>x.CourseCode).HasMaxLength(80).IsRequired();b.Property(x=>x.CourseTitle).HasMaxLength(240).IsRequired();b.Property(x=>x.AssessmentMode).HasConversion<string>().HasMaxLength(40);b.Property(x=>x.DeliveryMethod).HasConversion<string>().HasMaxLength(40);b.Property(x=>x.PassingScore).HasPrecision(5,2);b.HasIndex(x=>new{x.PositionId,x.CourseCode}).IsUnique();b.HasIndex(x=>x.ControlledDocumentId);b.HasOne<Qms.Domain.Organization.Position>().WithMany().HasForeignKey(x=>x.PositionId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Qms.Domain.Documents.ControlledDocument>().WithMany().HasForeignKey(x=>x.ControlledDocumentId).OnDelete(DeleteBehavior.Restrict);}}
